lessons.solution_code:
const createButton = (text) => ({
    tag: 'button',
    textContent: text,
    disabled: false
});
module.exports = { createButton };

tests.unittest_code:
const { createButton } = solution;
const b = createButton('Click Me');
if (b.textContent !== 'Click Me') throw new Error('Button text mismatch');
if (b.tag !== 'button') throw new Error('Expected tag button');
if (b.disabled !== false) throw new Error('Expected disabled false');

